class Solution {
    public int jump(int[] nums) {
        int n = nums.length;
        if(n<=1) return 0;
        // steps : 跳跃次数
        int steps = 0;
        // currentEnd : 当前这一步能达到的最远距离
        int currentEnd = 0;
        int maxReach = 0;
        for(int i=0; i<n-1; i++){
            maxReach = Math.max(maxReach, i+nums[i]);
            if(i == currentEnd){
                steps++;
                currentEnd = maxReach;
            }
        }
        return steps;
    }
}
